-- Ingredient canonicalization: collapse 5,753 name variants into 2,497 canonical
-- ingredients and delete 17 junk fragments, per docs/ingredient-merges.csv.
-- Reduces sss_ingredients 21,192 -> 15,422.
--
-- Plain SQL (no plpgsql/DO block) so it runs identically via `supabase db push`,
-- psql, or the Supabase SQL editor. Session temp tables are dropped explicitly.
-- Run inside a transaction (db push wraps migrations; the SQL editor runs the
-- whole script atomically) so it fully applies or not at all.
--
-- Repoint is collision-proof: a product that lists two variants of the same
-- canonical, or a variant plus the canonical itself, collapses to ONE join row
-- (this is what a naive UPDATE got wrong -> duplicate-PK rollback).

DROP TABLE IF EXISTS _merge_map;
DROP TABLE IF EXISTS _del_names;
DROP TABLE IF EXISTS _merge_ids;
DROP TABLE IF EXISTS _repoint;
DROP TABLE IF EXISTS _del_ids;

CREATE TEMP TABLE _merge_map (variant text, canonical text);
