-- Resolve names -> ids. Variants are disjoint from canonicals (no chains),
-- and every ingredient_name is unique, so this is an exact single-level map.
CREATE TEMP TABLE _merge_ids AS
SELECT v.ingredient_id AS variant_id, c.ingredient_id AS canonical_id
FROM _merge_map m
JOIN sss_ingredients v ON v.ingredient_name = m.variant
JOIN sss_ingredients c ON c.ingredient_name = m.canonical
WHERE v.ingredient_id <> c.ingredient_id;

-- Target canonical join rows, deduped per (product, canonical); keep earliest position.
CREATE TEMP TABLE _repoint AS
SELECT j.product_id, m.canonical_id AS ingredient_id, MIN(j.position) AS position
FROM sss_product_ingredients_join j
JOIN _merge_ids m ON m.variant_id = j.ingredient_id
GROUP BY j.product_id, m.canonical_id;

-- 1. Remove every variant join row, then insert one canonical row per product
--    where it is not already linked. No duplicate (product_id, ingredient_id) possible.
DELETE FROM sss_product_ingredients_join j
USING _merge_ids m WHERE j.ingredient_id = m.variant_id;

INSERT INTO sss_product_ingredients_join (product_id, ingredient_id, position)
SELECT r.product_id, r.ingredient_id, r.position
FROM _repoint r
WHERE NOT EXISTS (
  SELECT 1 FROM sss_product_ingredients_join k
  WHERE k.product_id = r.product_id AND k.ingredient_id = r.ingredient_id);

-- 2. Delete merged variant ingredient rows (no join rows reference them now).
DELETE FROM sss_ingredients i USING _merge_ids m WHERE i.ingredient_id = m.variant_id;

-- 3. Delete junk (tier 6) ingredients and their join rows.
CREATE TEMP TABLE _del_ids AS
SELECT ingredient_id FROM sss_ingredients WHERE ingredient_name IN (SELECT name FROM _del_names);
DELETE FROM sss_product_ingredients_join WHERE ingredient_id IN (SELECT ingredient_id FROM _del_ids);
DELETE FROM sss_ingredients WHERE ingredient_id IN (SELECT ingredient_id FROM _del_ids);

-- 4. Recompute denormalized aggregates from the (now canonical) join table.
UPDATE sss_ingredients i
SET product_count = COALESCE(s.cnt, 0), avg_position = s.avgpos
FROM (SELECT ingredient_id, COUNT(*) AS cnt, AVG(position) AS avgpos
      FROM sss_product_ingredients_join GROUP BY ingredient_id) s
WHERE s.ingredient_id = i.ingredient_id;
UPDATE sss_ingredients i SET product_count = 0, avg_position = NULL
WHERE NOT EXISTS (SELECT 1 FROM sss_product_ingredients_join j WHERE j.ingredient_id = i.ingredient_id);

UPDATE sss_products p
SET ingredient_count = COALESCE(s.cnt, 0)
FROM (SELECT product_id, COUNT(*) AS cnt
      FROM sss_product_ingredients_join GROUP BY product_id) s
WHERE s.product_id = p.product_id;
UPDATE sss_products p SET ingredient_count = 0
WHERE NOT EXISTS (SELECT 1 FROM sss_product_ingredients_join j WHERE j.product_id = p.product_id);

-- 5. Recompute like_count (global favorites through the join) for ingredients.
UPDATE sss_ingredients i
SET like_count = COALESCE(c.cnt, 0)
FROM (SELECT j.ingredient_id, COUNT(*) AS cnt
      FROM product_favorites pf
      JOIN sss_product_ingredients_join j ON j.product_id = pf.product_id
      GROUP BY j.ingredient_id) c
WHERE c.ingredient_id = i.ingredient_id;
UPDATE sss_ingredients i SET like_count = 0
WHERE NOT EXISTS (SELECT 1 FROM product_favorites pf
                  JOIN sss_product_ingredients_join j ON j.product_id = pf.product_id
                  WHERE j.ingredient_id = i.ingredient_id);

DROP TABLE IF EXISTS _merge_map;
DROP TABLE IF EXISTS _del_names;
DROP TABLE IF EXISTS _merge_ids;
DROP TABLE IF EXISTS _repoint;
DROP TABLE IF EXISTS _del_ids;
